-- DIVINOS GAMES — execute once in a fresh Supabase project.
begin;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade,role text not null default 'client' check(role in ('admin','client')),name text not null default '',avatar_url text,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,icon text not null default 'Gamepad2',created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',price numeric(12,2) not null check(price>0),compare_price numeric(12,2) not null default 0 check(compare_price>=0),cost numeric(12,2) not null default 0 check(cost>=0),stock int not null default 0 check(stock>=0),sku text not null unique,category_id uuid references public.categories,images jsonb not null default '[]' check(jsonb_typeof(images)='array'),is_featured bool not null default false,is_active bool not null default true,created_at timestamptz not null default now());
create table public.coupons(id uuid primary key default gen_random_uuid(),code text not null unique,discount_type text not null check(discount_type in ('percent','fixed')),value numeric(12,2) not null check(value>0 and (discount_type<>'percent' or value<=100)),min_order numeric(12,2) not null default 0 check(min_order>=0),max_uses int check(max_uses>=0),used_count int not null default 0 check(used_count>=0),expires_at timestamptz,is_active bool not null default true);
create table public.reviews(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,user_id uuid not null references public.profiles on delete cascade,rating int not null check(rating between 1 and 5),comment text not null check(length(comment)>=10),is_approved bool not null default false,created_at timestamptz not null default now(),unique(product_id,user_id));
create table public.orders(id uuid primary key default gen_random_uuid(),request_id uuid not null default gen_random_uuid(),user_id uuid not null references public.profiles,status text not null default 'pending' check(status in ('pending','paid','shipped','delivered','cancelled')),total numeric(12,2) not null check(total>=0),subtotal numeric(12,2) not null check(subtotal>=0),discount numeric(12,2) not null default 0,shipping numeric(12,2) not null default 0,payment_method text not null,shipping_address jsonb not null,coupon_code text,created_at timestamptz not null default now(),unique(user_id,request_id));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,product_id uuid not null references public.products,name text not null,image text not null,quantity int not null check(quantity>0),price numeric(12,2) not null check(price>0));
create table public.cart_items(user_id uuid not null references public.profiles on delete cascade,product_id uuid not null references public.products on delete cascade,quantity int not null check(quantity between 1 and 999),primary key(user_id,product_id));
create table public.wishlist(user_id uuid not null references public.profiles on delete cascade,product_id uuid not null references public.products on delete cascade,primary key(user_id,product_id));
create table public.settings(id text primary key,value jsonb not null);
insert into public.settings values('store','{"store_name":"DIVINOS GAMES","logo_url":"","hero_url":"","free_shipping":499}');
create index products_category on public.products(category_id);create index products_featured on public.products(is_featured) where is_active;create index orders_user on public.orders(user_id);create index orders_created on public.orders(created_at);create index reviews_product on public.reviews(product_id);create index order_items_order on public.order_items(order_id);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin
perform pg_advisory_xact_lock(718293);
insert into public.profiles(id,name,role) values(new.id,coalesce(new.raw_user_meta_data->>'name','Gamer'),case when not exists(select 1 from public.profiles) then 'admin' else 'client' end);
return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.coupons enable row level security;alter table public.reviews enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.cart_items enable row level security;alter table public.wishlist enable row level security;alter table public.settings enable row level security;
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_admin() or exists(select 1 from public.reviews r where r.user_id=profiles.id and r.is_approved));
create policy profiles_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
revoke update on public.profiles from authenticated;grant update(name,avatar_url) on public.profiles to authenticated;
create policy categories_read on public.categories for select using(true);create policy categories_admin on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy products_read on public.products for select using(is_active or public.is_admin());create policy products_admin on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy coupons_admin on public.coupons for all using(public.is_admin()) with check(public.is_admin());
create policy reviews_read on public.reviews for select using(is_approved or user_id=auth.uid() or public.is_admin());create policy reviews_insert on public.reviews for insert with check(user_id=auth.uid() and not is_approved);create policy reviews_admin on public.reviews for all using(public.is_admin()) with check(public.is_admin());
create policy orders_read on public.orders for select using(user_id=auth.uid() or public.is_admin());create policy orders_admin on public.orders for update using(public.is_admin()) with check(public.is_admin());
create policy order_items_read on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and(o.user_id=auth.uid() or public.is_admin())));
create policy cart_own on public.cart_items for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy wishlist_own on public.wishlist for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy settings_read on public.settings for select using(true);create policy settings_admin on public.settings for all using(public.is_admin()) with check(public.is_admin());
create function public.validate_coupon(p_code text,p_subtotal numeric) returns jsonb language plpgsql security definer set search_path='' as $$declare c public.coupons;begin select * into c from public.coupons where code=upper(trim(p_code)) and is_active and(expires_at is null or expires_at>now()) and(max_uses is null or max_uses=0 or used_count<max_uses) and min_order<=p_subtotal;if not found then raise exception 'Cupom inválido, expirado ou mínimo não atingido';end if;return jsonb_build_object('code',c.code,'discount_type',c.discount_type,'value',c.value,'min_order',c.min_order);end;$$;
-- Mock payment only. This RPC never accepts a price/total from the browser.
-- Replace the paid transition with a verified provider webhook before accepting money.
create function public.checkout(p_items jsonb,p_address jsonb,p_payment text,p_coupon text default '',p_request_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path='' as $$
declare product public.products;coupon public.coupons;item record;new_order public.orders;sub numeric:=0;disc numeric:=0;delivery numeric:=0;threshold numeric:=499;begin
if auth.uid() is null then raise exception 'Autenticação necessária';end if;
if p_request_id is null then raise exception 'Identificador da compra necessário';end if;
perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_request_id::text,0));
select * into new_order from public.orders where user_id=auth.uid() and request_id=p_request_id;if found then return to_jsonb(new_order);end if;
if p_payment not in('mock_pix','mock_card') then raise exception 'Somente pagamento demonstrativo habilitado';end if;
if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 or jsonb_array_length(p_items)>100 then raise exception 'Carrinho inválido';end if;
if coalesce(length(p_address->>'name'),0)<3 or coalesce(p_address->>'cep','')!~'^\d{5}-?\d{3}$' or coalesce(length(p_address->>'street'),0)<3 or coalesce(length(p_address->>'number'),0)=0 or coalesce(length(p_address->>'city'),0)<2 or coalesce(length(p_address->>'state'),0)<>2 then raise exception 'Endereço inválido';end if;
-- Group duplicate products and lock in a deterministic order to avoid overselling/deadlocks.
for item in select product_id,sum(quantity)::int as quantity from jsonb_to_recordset(p_items) as x(product_id uuid,quantity int) group by product_id order by product_id loop
if item.quantity is null or item.quantity<1 or item.quantity>999 then raise exception 'Quantidade inválida';end if;
select * into product from public.products where id=item.product_id and is_active for update;
if not found or product.stock<item.quantity then raise exception 'Produto indisponível ou estoque insuficiente';end if;sub:=sub+product.price*item.quantity;
end loop;
if trim(p_coupon)<>'' then select * into coupon from public.coupons where code=upper(trim(p_coupon)) for update;if not found or not coupon.is_active or(coupon.expires_at is not null and coupon.expires_at<=now()) or(coupon.max_uses>0 and coupon.used_count>=coupon.max_uses) or sub<coupon.min_order then raise exception 'Cupom inválido';end if;disc:=least(sub,case when coupon.discount_type='percent' then round(sub*coupon.value/100,2) else coupon.value end);update public.coupons set used_count=used_count+1 where id=coupon.id;end if;
select coalesce((value->>'free_shipping')::numeric,499) into threshold from public.settings where id='store';delivery:=case when sub>=coalesce(threshold,499) then 0 else 24.9 end;
insert into public.orders(user_id,request_id,status,total,subtotal,discount,shipping,payment_method,shipping_address,coupon_code) values(auth.uid(),p_request_id,'pending',sub-disc+delivery,sub,disc,delivery,p_payment,p_address,coupon.code) returning * into new_order;
for item in select product_id,sum(quantity)::int as quantity from jsonb_to_recordset(p_items) as x(product_id uuid,quantity int) group by product_id loop
select * into product from public.products where id=item.product_id;insert into public.order_items(order_id,product_id,name,image,quantity,price) values(new_order.id,product.id,product.name,coalesce(product.images->>0,''),item.quantity,product.price);update public.products set stock=stock-item.quantity where id=product.id;end loop;
update public.orders set status='paid' where id=new_order.id returning * into new_order;delete from public.cart_items where user_id=auth.uid();return to_jsonb(new_order);end;$$;
revoke all on function public.checkout(jsonb,jsonb,text,text,uuid) from public,anon;grant execute on function public.checkout(jsonb,jsonb,text,text,uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']),('avatars','avatars',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy images_read on storage.objects for select using(bucket_id in('product-images','avatars'));
create policy images_admin on storage.objects for insert with check(bucket_id='product-images' and public.is_admin());create policy images_admin_update on storage.objects for update using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());create policy images_admin_delete on storage.objects for delete using(bucket_id='product-images' and public.is_admin());
create policy avatar_insert on storage.objects for insert with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);create policy avatar_update on storage.objects for update using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);create policy avatar_delete on storage.objects for delete using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
insert into public.categories(name,slug,icon) values('Consoles','consoles','Gamepad2'),('Jogos','jogos','Disc3'),('Acessórios','acessorios','Headphones'),('PC Gamer','pc-gamer','Monitor');
insert into public.products(name,slug,description,price,compare_price,cost,stock,sku,category_id,images,is_featured)
select v.name,v.slug,'Produto original com nota fiscal e garantia de 12 meses. Performance e qualidade para o seu próximo nível com DIVINOS GAMES.',v.price,v.compare_price,v.price*.65,v.stock,'DG-'||lpad(v.n::text,4,'0'),c.id,(select jsonb_agg('https://picsum.photos/seed/divinos-'||v.n||'-'||s||'/600') from generate_series(1,5) s),v.n<=4 from(values
(1,'PlayStation 5 Slim • 1TB','playstation-5-slim-1tb',3499.90,3999.90,18,'consoles'),(2,'Controle DualSense • Midnight Black','controle-dualsense-midnight-black',399.90,499.90,8,'acessorios'),(3,'Headset Gamer HyperX Cloud III','headset-gamer-hyperx-cloud-iii',499.90,649.90,12,'acessorios'),(4,'Nintendo Switch OLED • 64GB','nintendo-switch-oled-64gb',2199.90,2599.90,6,'consoles'),(5,'PC Gamer RTX 4060 • Ryzen 5','pc-gamer-rtx-4060-ryzen-5',4599.90,5499.90,3,'pc-gamer'),(6,'God of War Ragnarök • PS5','god-of-war-ragnarok-ps5',199.90,299.90,23,'jogos'),(7,'Xbox Series X • 1TB','xbox-series-x-1tb',3899.90,4499.90,7,'consoles'),(8,'Teclado Mecânico RGB Pro','teclado-mecanico-rgb-pro',249.90,349.90,15,'acessorios'),(9,'Marvel’s Spider-Man 2 • PS5','marvels-spider-man-2-ps5',249.90,349.90,10,'jogos'),(10,'Mouse Gamer Logitech G Pro','mouse-gamer-logitech-g-pro',349.90,449.90,20,'acessorios'),(11,'Monitor Gamer 27” • 165Hz','monitor-gamer-27-165hz',1199.90,1499.90,4,'pc-gamer'),(12,'EA Sports FC 25 • PS5','ea-sports-fc-25-ps5',189.90,299.90,0,'jogos')) v(n,name,slug,price,compare_price,stock,category) join public.categories c on c.slug=v.category;
insert into public.coupons(code,discount_type,value,min_order,max_uses,expires_at) values('DIVINOS10','percent',10,0,1000,now()+interval '1 year'),('BEMVINDO50','fixed',50,250,500,now()+interval '1 year');
commit;
